code='''from collections import deque

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    # A partial horizontal run can be completed when the same color has a full row.
    full_colors={a[r][0] for r in range(h) if len(set(a[r]))==1}
    line_targets=[]
    for r in range(h):
        color=a[r][0]
        if color not in full_colors: continue
        k=0
        while k<w and a[r][k]==color: k+=1
        if 0<k<w and len(set(a[r][k:]))==1 and a[r][k]!=color:
            line_targets.extend((r,c) for c in range(k,w))

    # Locate the large uniform separator between two repeated panels.
    full=[(r,a[r][0]) for r in range(h) if len(set(a[r]))==1]
    runs=[]
    for r,c in full:
        if runs and r==runs[-1][-1][0]+1 and c==runs[-1][-1][1]: runs[-1].append((r,c))
        else: runs.append([(r,c)])
    candidates=[]
    for run in runs:
        r0,r1=run[0][0],run[-1][0]; bg=run[0][1]
        above=any(any(v!=bg for v in a[r]) for r in range(r0))
        below=any(any(v!=bg for v in a[r]) for r in range(r1+1,h))
        if above and below: candidates.append(run)
    if candidates:
        sep=min(candidates,key=len); sr0,sr1=sep[0][0],sep[-1][0]; bg=sep[0][1]
        top=[r for r in range(sr0) if any(v!=bg for v in a[r])]
        bot=[r for r in range(sr1+1,h) if any(v!=bg for v in a[r])]
        if top and bot:
            t0,t1=min(top),max(top); b0,b1=min(bot),max(bot)
            if t1-t0==b1-b0:
                th=t1-t0+1
                masks=[]
                # Either panel can contain the missing segment.
                for mode in (0,1):
                    mask=[[ (a[t0+i][c]==bg and a[b0+i][c]!=bg) if mode==0 else (a[t0+i][c]!=bg and a[b0+i][c]==bg) for c in range(w)] for i in range(th)]
                    seen=set(); comps=[]
                    for r in range(th):
                        for c in range(w):
                            if not mask[r][c] or (r,c) in seen: continue
                            q=[(r,c)]; seen.add((r,c)); comp=[]
                            while q:
                                x,y=q.pop(); comp.append((x,y))
                                for z in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                                    if 0<=z[0]<th and 0<=z[1]<w and mask[z[0]][z[1]] and z not in seen:
                                        seen.add(z); q.append(z)
                            comps.append(comp)
                    if comps: masks.append((mode,max(comps,key=len)))
                if masks:
                    if line_targets:
                        chosen=[item for item in masks if item[0]==1]
                    else:
                        chosen=[item for item in masks if item[0]==0]
                    for mode,comp in chosen:
                        for r,c in comp:
                            a[(t0 if mode==0 else b0)+r][c]=1
    for r,c in line_targets: a[r][c]=1
    return a
'''
